def is_anagram(a, b):
    norm = lambda s: sorted(c for c in s.lower() if not c.isspace())
    return norm(a) == norm(b)

def fib(n):
    a, b = 0, 1
    for _ in range(n):
        a, b = b, a + b
    return a

def binary_search(sorted_list, target):
    lo, hi = 0, len(sorted_list) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if sorted_list[mid] == target:
            return mid
        if sorted_list[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1

def longest_common_prefix(strs):
    if not strs:
        return ""
    shortest = min(strs, key=len)
    for i, c in enumerate(shortest):
        for s in strs:
            if s[i] != c:
                return shortest[:i]
    return shortest

def valid_ipv4(s):
    parts = s.split(".")
    if len(parts) != 4:
        return False
    for p in parts:
        if not p.isdigit():
            return False
        if len(p) > 1 and p[0] == "0":
            return False
        if int(p) > 255:
            return False
    return True

def parse_version(v):
    if not v:
        raise ValueError("empty version")
    parts = v.split(".")
    out = []
    for p in parts:
        if not p.isdigit():
            raise ValueError("bad component: %r" % p)
        out.append(int(p))
    return tuple(out)

