    in the order they appeared in the input.

    >>> group_by_length(["a", "bb", "cc", "d"])
    {1: ['a', 'd'], 2: ['bb', 'cc']}
    >>> group_by_length([])
    {}
    """

canonical_solution:
def group_by_length(words):
    out = {}
    for w in words:
        out.setdefault(len(w), []).append(w)
    return out

